package com.tecsup.medico.model; import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.time.LocalTime;
@Entity @Table(name="horario_medico")public class HorarioMedico{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="id_horario")private Long id;@ManyToOne(optional=false)@JoinColumn(name="id_medico",nullable=false)private Medico medico;@NotBlank @Column(length=15)private String diaSemana;private LocalTime horaInicio;private LocalTime horaFin;public Long getId(){return id;}public Medico getMedico(){return medico;}public void setMedico(Medico x){medico=x;}public String getDiaSemana(){return diaSemana;}public void setDiaSemana(String x){diaSemana=x;}public LocalTime getHoraInicio(){return horaInicio;}public void setHoraInicio(LocalTime x){horaInicio=x;}public LocalTime getHoraFin(){return horaFin;}public void setHoraFin(LocalTime x){horaFin=x;}}
